/* 1. Оболочка страницы и её очистка от обтекания */
.shell {
    max-width: 1240px;
    margin: 0 auto;
    padding: 18px 90px 46px 24px;
}

.shell::after {
    content: "";
    display: table;
    clear: both;
}

/* 2. Меню: плавающий блок слева */
.sidebar {
    float: left;
    width: 228px;
    margin: 0 28px 18px 0;
    padding: 16px 0;
    background-color: var(--surface);
    border: 1px solid var(--line);
    border-radius: var(--radius);
    box-shadow: var(--shadow);
}

.menu {
    display: flex;
    flex-direction: column;
}

/* … правила подписей, пунктов меню и их состояний опущены … */

.menu__more {
    color: var(--muted);
}

/* … правила основной колонки и ленты комментариев опущены … */

/* 6. Фиксированная панель соцсетей */
.social {
    position: fixed;
    top: 240px;
    right: 16px;
    display: flex;
    flex-direction: column;
    gap: 10px;
    z-index: 10;
}

/* … оформление круглых ссылок панели опущено … */

/* 2. Сетка трёх колонок */
.news-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 20px;
    align-items: start;
}

.news-column {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

/* 3. Карточка новости */
.news-card {
    padding: 16px 16px 18px;
    background-color: var(--surface);
    border: 1px solid var(--line);
    border-radius: var(--radius);
    box-shadow: var(--shadow);
}

.news-card__title {
    margin: 0 0 10px;
    padding-bottom: 8px;
    border-bottom: 2px solid var(--red);
    font-size: 17px;
}

.news-card__image {
    display: block;
    width: 100%;
    margin: 0 0 10px;
    border-radius: var(--radius);
}

/* … правила текста и даты новости, горизонтальной карточки опущены … */

/* 3. Миниатюра как ссылка */
.gallery-item__link {
    display: block;
    position: relative;
    overflow: hidden;
    border-radius: var(--radius);
    background-color: #c6d8e8;
}

.gallery-item__image {
    display: block;
    width: 100%;
    aspect-ratio: 3 / 2;
    object-fit: cover;
    transition: transform 0.2s ease-out;
}

.gallery-item__link:hover .gallery-item__image,
.gallery-item__link:focus .gallery-item__image {
    transform: scale(1.04);
}

/* … правила подписи, текста и подсказки миниатюры опущены … */

/* 3. Первый экран: две колонки на flex */
.hero {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 32px;
    max-width: 1120px;
    margin: 0 auto;
    padding: 36px 24px 28px;
}

.hero__text {
    flex: 1 1 340px;
    min-width: 0;
}

.hero__title {
    margin: 0 0 12px;
    font-size: 32px;
    line-height: 1.15;
}

.hero__lead {
    color: var(--muted);
    font-size: 16px;
}

/* … правила кнопки и карточек работы опущены … */

.works {
    display: flex;
    flex-wrap: wrap;
    gap: 16px;
    margin: 0;
    padding: 0;
    list-style: none;
}
